mapper.select:
SELECT COUNT(*)
FROM RENTAL_EXTENSION
WHERE RENTAL_ID = #{rentalId}

mapper.delete:
DELETE FROM RENTAL_EXTENSION
WHERE EXTENSION_ID = #{extensionId}
AND RENTAL_ID = #{rentalId}

mapper.update:
UPDATE RENTALS
SET RETURN_DATE = DATE_ADD(RETURN_DATE, INTERVAL #{extensionDays} DAY)
WHERE RENTAL_ID = #{rentalId}

UPDATE RENTAL_EXTENSION_ORDER
SET STATUS = #{status}
WHERE EXTENSION_ORDER_ID = #{extensionOrderId}

mapper.select:
SELECT RENTAL_ID AS rentalId
FROM RENTALS
WHERE RENTAL_ID = #{rentalId}
AND GUEST_PHONE = #{guestPhone}

SELECT o.OVERDUE_ORDER_ID, o.RENTAL_ID, o.OVERDUE_DAYS, o.OVERDUE_FEE, o.STATUS, o.USER_ID, o.GUEST_TOKEN, o.RETURN_ZIPCODE, o.RETURN_ADDRESS, o.RETURN_DETAILED_ADDRESS,
p.PRODUCT_NAME, (SELECT pi.IMG_URL FROM PRODUCT_IMG pi WHERE pi.PRODUCT_ID = p.PRODUCT_ID AND pi.IS_MAIN = 'Y' LIMIT 1) AS IMG_URL
FROM RENTAL_OVERDUE_ORDER o JOIN RENTALS r ON o.RENTAL_ID = r.RENTAL_ID JOIN ORDER_ITEM oi ON r.ITEM_ID = oi.ITEM_ID JOIN PRODUCT p ON oi.PRODUCT_ID = p.PRODUCT_ID WHERE o.OVERDUE_ORDER_ID = #{overdueOrderId}

mapper.update:
UPDATE RENTAL_OVERDUE_ORDER
SET STATUS = #{status}
WHERE OVERDUE_ORDER_ID = #{overdueOrderId}

UPDATE RENTALS
SET OVERDUE_NOTIFY_STAGE = #{stage}
WHERE RENTAL_ID = #{rentalId}
